//! The cartridge database (lot CARTDB): what an iNES 1.0 header cannot say about a cartridge —
//! the chip revision, the submapper, the real work and save RAM, the battery, the region — looked
//! up by the CRC-32 of the ROM data (`builtin_patches::data_crc`, header and trainer excluded) and
//! turned into the NES 2.0 header the dump should have carried.
//!
//! The data is `data/cartdb.csv`, generated by `tools/cartdb_from_mesen.py` from Mesen's game
//! database (GPL-3, like Zaxnes), itself built from `NewRisingSun`'s NES 2.0 header database,
//! `BootGod`'s `NesCartDB` and Nestopia UE's database. It is read at load only, by bisection over the
//! sorted lines; nothing here runs during emulation.
//!
//! **A NES 2.0 header is never corrected**: it can already say everything the database knows,
//! and a dumper who wrote one meant it. Nor is an iNES 1.0 one whose PRG or CHR size disagrees
//! with the database's entry, which is then a different cartridge with a colliding CRC or a
//! trimmed dump.

use super::InesHeader;
use crate::{NametableMirroring, NesRegion};

/// The generated table, one cartridge per line, sorted by CRC.
const TABLE: &str = include_str!("../../data/cartdb.csv");

/// One cartridge of the database.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CartEntry {
    /// `NesNtsc`, `NesPal`, `Famicom`, `Dendy`, `Playchoice` or `VsSystem`.
    pub system: &'static str,
    /// iNES / NES 2.0 mapper number.
    pub mapper: i32,
    /// NES 2.0 submapper, when the database gives one.
    pub submapper: Option<i32>,
    /// PRG-ROM size in KiB.
    pub prg_kib: usize,
    /// CHR-ROM size in KiB.
    pub chr_kib: usize,
    /// CHR-RAM size in KiB.
    pub chr_ram_kib: usize,
    /// Volatile PRG-RAM in KiB.
    pub work_ram_kib: usize,
    /// Battery-backed PRG-RAM in KiB.
    pub save_ram_kib: usize,
    /// Whether the save RAM is battery backed.
    pub battery: bool,
    /// `h`, `v` or `4` (four-screen), as the database writes it.
    pub mirroring: char,
    /// The mapper chip as printed on it (`MMC3A`, `MMC1B2`, …), empty when unknown.
    pub chip: &'static str,
}

/// The entry of the cartridge whose ROM data has CRC-32 `crc`.
#[must_use]
pub fn lookup(crc: u32) -> Option<CartEntry> {
    let key = format!("{crc:08X}");
    let lines: Vec<&'static str> = TABLE
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .collect();
    let index = lines
        .binary_search_by(|line| line.get(..8).unwrap_or("").cmp(key.as_str()))
        .ok()?;
    parse(lines.get(index)?)
}

fn parse(line: &'static str) -> Option<CartEntry> {
    let f: Vec<&'static str> = line.split(',').collect();
    let number = |i: usize| f.get(i).and_then(|v| v.parse::<usize>().ok()).unwrap_or(0);
    Some(CartEntry {
        system: f.get(1)?,
        mapper: f.get(2)?.parse().ok()?,
        submapper: f.get(3).and_then(|v| v.parse().ok()),
        prg_kib: number(4),
        chr_kib: number(5),
        chr_ram_kib: number(6),
        work_ram_kib: number(7),
        save_ram_kib: number(8),
        battery: f.get(9).is_some_and(|v| *v == "1"),
        mirroring: f.get(10).and_then(|v| v.chars().next()).unwrap_or('h'),
        chip: f.get(11).copied().unwrap_or(""),
    })
}

impl CartEntry {
    /// The NES 2.0 submapper the entry stands for: the database's own when it gives a nonzero
    /// one, otherwise the one its **chip** implies where Zaxnes's boards distinguish revisions by
    /// submapper — mapper 4's MMC3A is submapper 4 (the "old" IRQ) and its MMC6 submapper 1,
    /// mapper 1's MMC1A submapper 3 (`$E000` bit 4 not wired) (nesdev, "NES 2.0 submappers").
    #[must_use]
    pub fn submapper(&self) -> i32 {
        match self.submapper {
            Some(value) if value != 0 => value,
            _ => match (self.mapper, self.chip) {
                (4, "MMC3A") => 4,
                (4, chip) if chip.starts_with("MMC6") => 1,
                (1, "MMC1A") => 3,
                _ => 0,
            },
        }
    }

    /// The region the entry's system runs at.
    #[must_use]
    pub fn region(&self) -> NesRegion {
        match self.system {
            "NesPal" => NesRegion::Pal,
            "Dendy" => NesRegion::Dendy,
            _ => NesRegion::Ntsc,
        }
    }
}

/// A header the database corrects, and what it changed, one short phrase per field.
#[derive(Debug, Clone)]
pub struct Correction {
    /// The NES 2.0 header the dump should have carried.
    pub header: InesHeader,
    /// What differs from the file's header, e.g. `mapper 4 -> 4.4 (MMC3A)`.
    pub changes: Vec<String>,
}

/// The header the database gives for a dump whose header is `header` and whose data has CRC-32
/// `crc`; `None` when the header is NES 2.0, the dump is unknown, its sizes disagree with the
/// entry, or the entry changes nothing.
#[must_use]
pub fn corrected_header(header: &InesHeader, crc: u32) -> Option<Correction> {
    if header.is_nes20 {
        return None;
    }
    let entry = lookup(crc)?;
    if entry.prg_kib * 1024 != header.prg_rom_size || entry.chr_kib * 1024 != header.chr_rom_size {
        return None;
    }
    let mut fixed = header.clone();
    let mut changes = Vec::new();

    // The mapper number itself is never changed: a dump whose header names another board than the
    // database's plays as the header says (the iam8bit Mega Man 2, mapper 2 in its header and 30
    // in the database, loses its background on 30). Only what the header could not say for the
    // same board is taken.
    if entry.mapper != header.mapper {
        return None;
    }
    let submapper = entry.submapper();
    if submapper != header.submapper {
        let chip = if entry.chip.is_empty() {
            String::new()
        } else {
            format!(" ({})", entry.chip)
        };
        changes.push(format!(
            "submapper {} -> {}{chip}",
            header.submapper, submapper
        ));
        fixed.submapper = submapper;
    }

    let prg_ram =
        ((entry.work_ram_kib + entry.save_ram_kib) * 1024).max(InesHeader::DEFAULT_PRG_RAM_SIZE);
    if prg_ram != header.prg_ram_size {
        changes.push(format!(
            "PRG-RAM {} -> {} KiB",
            header.prg_ram_size / 1024,
            prg_ram / 1024
        ));
        fixed.prg_ram_size = prg_ram;
    }
    fixed.byte10 = shift_of(entry.work_ram_kib * 1024) | (shift_of(entry.save_ram_kib * 1024) << 4);

    // CHR-RAM larger than the 32 KiB an iNES 1.0 image gets is taken; a smaller one is not. The
    // real 8 KiB of an UNROM or SxROM changes nothing a game can see, and a different size would
    // turn away every savestate already made of these games.
    if header.chr_rom_size == 0 && entry.chr_ram_kib * 1024 > header.chr_ram_size {
        changes.push(format!(
            "CHR-RAM {} -> {} KiB",
            header.chr_ram_size / 1024,
            entry.chr_ram_kib
        ));
        fixed.chr_ram_size = entry.chr_ram_kib * 1024;
    }

    if entry.battery != header.has_battery {
        changes.push(format!(
            "battery {} -> {}",
            header.has_battery, entry.battery
        ));
        fixed.has_battery = entry.battery;
    }

    if entry.mirroring == '4' && header.mirroring != NametableMirroring::FourScreen {
        changes.push("mirroring -> four-screen".to_owned());
        fixed.mirroring = NametableMirroring::FourScreen;
    }

    let region = entry.region();
    if region != header.region {
        changes.push(format!("region {:?} -> {region:?}", header.region));
        fixed.region = region;
    }

    if changes.is_empty() {
        return None;
    }
    fixed.is_nes20 = true;
    fixed.is_dirty = false;
    Some(Correction {
        header: fixed,
        changes,
    })
}

/// The NES 2.0 size shift of `bytes` (64 << shift), 0 for none.
fn shift_of(bytes: usize) -> u8 {
    (1..=14u8)
        .find(|shift| 64usize << shift == bytes)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_and_parses() {
        let mut last = String::new();
        let mut count = 0;
        for line in TABLE
            .lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
        {
            let crc = line.get(..8).unwrap_or("").to_owned();
            assert!(crc > last, "not sorted at {line}");
            assert!(parse(line).is_some(), "{line}");
            last = crc;
            count += 1;
        }
        assert!(count > 10_000);
    }

    #[test]
    fn a_known_mmc3c_cartridge_is_found() {
        let entry = lookup(0x0013_88B3).unwrap();
        assert_eq!(
            (4, "MMC3C", "NesPal"),
            (entry.mapper, entry.chip, entry.system)
        );
        assert_eq!(None, lookup(0xFFFF_FFF1));
    }

    #[test]
    fn the_chip_gives_the_submapper() {
        let mut entry = lookup(0x0013_88B3).unwrap();
        assert_eq!(0, entry.submapper());
        entry.chip = "MMC3A";
        assert_eq!(4, entry.submapper());
        entry.mapper = 1;
        entry.chip = "MMC1A";
        assert_eq!(3, entry.submapper());
    }

    /// An iNES 1.0 header: `prg` 16 KiB banks, `chr` 8 KiB banks, `mapper` in bytes 6 and 7.
    fn ines1(prg: u8, chr: u8, mapper: u8) -> InesHeader {
        let mut image = vec![0u8; 16 + usize::from(prg) * 16_384 + usize::from(chr) * 8_192];
        image[..4].copy_from_slice(b"NES");
        image[4] = prg;
        image[5] = chr;
        image[6] = mapper << 4;
        image[7] = mapper & 0xF0;
        InesHeader::try_parse(&image).unwrap()
    }

    #[test]
    fn super_mario_bros_3_japan_is_an_mmc3a() {
        let correction = corrected_header(&ines1(16, 16, 4), 0xE7DD_FEE3).unwrap();
        assert_eq!(
            (4, 4, true),
            (
                correction.header.mapper,
                correction.header.submapper,
                correction.header.is_nes20
            )
        );
    }

    #[test]
    fn the_mapper_number_is_never_changed() {
        // The iam8bit Mega Man 2: mapper 2 in its header, 30 in the database.
        assert!(corrected_header(&ines1(16, 0, 2), 0x891C_14BC).is_none());
    }

    #[test]
    fn a_nes_2_0_header_is_kept() {
        let mut header = ines1(16, 16, 4);
        header.is_nes20 = true;
        assert!(corrected_header(&header, 0xE7DD_FEE3).is_none());
    }
}
